using System;using System.IO;using System.Linq;using IdleIntelligence.Core;using NUnit.Framework;using UnityEngine;
namespace IdleIntelligence.Tests
{
 [Serializable] public sealed class IndustryCase{public string name,action,id;public int amount;public double at,researchWork,forgeCost,forgeWork;public double[] forgeComponents;public NumberData researchPrice;public StateData before,expected;public PrestigeMetrics rates;}
 [Serializable] public sealed class IndustryCases{public string scope;public IndustryCase[] cases;}
 public sealed class IndustryParityTests
 {
  static void Near(ScientificNumber a,NumberData b,string name){var n=ScientificNumber.FromData(b);if(n.IsZero)Assert.That(a.IsZero,Is.True,name);else Assert.That(a.Log10(),Is.EqualTo(n.Log10()).Within(2e-10),name);}
  [Test]public void FullResearchIndustryAndTransactionsMatchTypeScript()
  {var f=JsonUtility.FromJson<IndustryCases>(File.ReadAllText(Path.Combine(Application.dataPath,"IdleIntelligence/Tests/EditMode/IndustryReferenceCases.json")));Assert.That(Balance.Research.Length,Is.EqualTo(26));Assert.That(f.cases.Length,Is.GreaterThan(140));foreach(var c in f.cases){var s=c.before.ToState();string original=JsonUtility.ToJson(StateData.From(s));int research=Game.ResearchIndex(c.id);if(research>=0){Near(Game.ResearchCost(s,research),c.researchPrice,c.name+" research price");Assert.That(Game.ResearchWork(s,research)/Game.WorkSpeed(s,true),Is.EqualTo(c.researchWork).Within(1e-7),c.name+" research time");}if(s.Workshop.inventory.Any(i=>i.id==c.id)){var q=Industry.ForgeQuote(s,c.id);Assert.That(q.Data,Is.EqualTo(c.forgeCost),c.name+" forge data");Assert.That(q.Components,Is.EqualTo(c.forgeComponents),c.name+" forge materials");Assert.That(Industry.ForgeWork(s,s.Workshop.inventory.First(i=>i.id==c.id)),Is.EqualTo(c.forgeWork).Within(1e-8),c.name+" forge work");}
   var n=s;switch(c.action){case "queue-analysis":n=MaterialAnalysis.Queue(s,Array.FindIndex(ItemBalance.Analyses,d=>d.Id==c.id));break;case "remove-analysis":n=MaterialAnalysis.RemoveQueued(s,c.amount);break;case "queue-research":n=PrestigeAutomation.QueueResearch(s,c.id);break;case "reset":n=PrestigeRules.Reset(s);break;case "axiom-reset":n=MetaRules.AxiomReset(s);break;case "research":n=Game.Research(s,c.id);break;case "train":n=Game.Train(s,c.id);break;case "forge":n=Industry.QueueForge(s,c.id);break;case "foundry":n=Industry.UpgradeFoundry(s,c.amount);break;case "remove":n=Industry.RemoveQueued(s,c.id);break;case "synthesis":n=Industry.Synthesize(s,Array.IndexOf(ItemBalance.ComponentIds,c.id));break;case "analysis":n=MaterialAnalysis.Start(s,0);break;case "breakthrough":n=Industry.BuyBreakthrough(s,c.id);break;case "convert":var t=Industry.QuoteConversion(s,c.amount);n=Industry.Convert(s,t);if(c.id=="repeat")n=Industry.Convert(n,t);break;case "lock":n=Workshop.Lock(s,c.id);break;case "upgrade":n=Workshop.Upgrade(s,c.id);break;case "advance":n=Game.Advance(s,c.at);break;}
   Assert.That(JsonUtility.ToJson(StateData.From(s)),Is.EqualTo(original),c.name+" pure");PrestigeParityTests.Numbers(n,c.expected,c.name);var e=c.expected.ToState();Assert.That(n.Industry.analysisQueue,Is.EqualTo(e.Industry.analysisQueue),c.name+" analysis FIFO");Assert.That(n.Industry.lastAnalysisAmounts,Is.EqualTo(e.Industry.lastAnalysisAmounts),c.name+" analysis receipt");Assert.That(n.Workshop.inventory.SelectMany(i=>i.materialBasis),Is.EqualTo(e.Workshop.inventory.SelectMany(i=>i.materialBasis)),c.name+" paid material basis");Assert.That(n.Industry.trainingStarted,Is.EqualTo(e.Industry.trainingStarted),c.name+" start counter");Assert.That(n.Training?.modelTransferEligible,Is.EqualTo(e.Training?.modelTransferEligible),c.name+" frozen eligibility");Assert.That(n.Workshop.researchFragments,Is.EqualTo(e.Workshop.researchFragments),c.name+" research fragments");Assert.That(n.Industry.conversionRevision,Is.EqualTo(e.Industry.conversionRevision),c.name+" conversion ticket");Assert.That(n.Industry.breakthroughs,Is.EqualTo(e.Industry.breakthroughs),c.name+" breakthroughs");Assert.That(n.Industry.synthesis?.id,Is.EqualTo(e.Industry.synthesis?.id),c.name+" synthesis");if(n.Industry.synthesis!=null){Assert.That(n.Industry.synthesis.done,Is.EqualTo(e.Industry.synthesis.done).Within(1e-7),c.name+" synthesis progress");Assert.That(n.Industry.synthesis.required,Is.EqualTo(e.Industry.synthesis.required),c.name+" synthesis contract");}Assert.That(n.Industry.foundries.Length,Is.EqualTo(e.Industry.foundries.Length),c.name+" station count");for(int i=0;i<n.Industry.foundries.Length;i++){var a=n.Industry.foundries[i];var b=e.Industry.foundries[i];Assert.That(a.level,Is.EqualTo(b.level),c.name+" station level");Assert.That(a.queue,Is.EqualTo(b.queue),c.name+" unpaid queue");Assert.That(a.active?.itemId,Is.EqualTo(b.active?.itemId),c.name+" paid forge");if(a.active!=null){Assert.That(a.active.required,Is.EqualTo(b.active.required).Within(1e-7),c.name+" forge frozen work");Assert.That(a.active.done,Is.EqualTo(b.active.done).Within(1e-7),c.name+" forge progress");Assert.That(a.active.components,Is.EqualTo(b.active.components),c.name+" forge payment");}}
   Near(Game.Compute(n),c.rates.compute,c.name+" compute");Near(Game.Income(n),c.rates.income,c.name+" revenue");Near(Game.DataRate(n),c.rates.dataRate,c.name+" data");Assert.That(Game.WorkSpeed(n),Is.EqualTo(c.rates.trainingSpeed).Within(1e-7),c.name+" training speed");Assert.That(Game.WorkSpeed(n,true),Is.EqualTo(c.rates.researchSpeed).Within(1e-7),c.name+" research speed");Game.Validate(n);
  }}
  [Test]public void PaidIndustryWorkSurvivesSaveAndRepeatedResumeWithoutDoubleReward()
  {var s=Game.New(1000);s.Workshop.starterGift=true;/* Starter materials previously claimed/spent: isolate one paid synthesis. Fresh first-production discovery is covered by TS/C# component flows. */s.Credits=ScientificNumber.From(100000);s.Data=ScientificNumber.From(100000);s=Industry.Synthesize(s,0);var loaded=StateData.From(s).ToState();var complete=Game.Advance(loaded,100000);Assert.That(complete.Industry.synthesis,Is.Null);Assert.That(complete.Workshop.components[0],Is.EqualTo(1));Assert.That(Game.Advance(complete,100000),Is.SameAs(complete));Assert.That(StateData.From(complete).ToState().Workshop.components[0],Is.EqualTo(1));}
 }
}
